package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for com.fasterxml.jackson.core.io.NumberInput.parseBigDecimal
 */
public class NumberInput_parseBigDecimal_TriageGen0Test {

    @Test
    public void testParseBigDecimal_ValidInteger() {
        String input = "123";
        BigDecimal expected = new BigDecimal("123");
        BigDecimal result = NumberInput.parseBigDecimal(input);
        assertEquals(expected, result);
    }

    @Test
    public void testParseBigDecimal_ValidDecimal() {
        String input = "123.456";
        BigDecimal expected = new BigDecimal("123.456");
        BigDecimal result = NumberInput.parseBigDecimal(input);
        assertEquals(expected, result);
    }

    @Test
    public void testParseBigDecimal_NegativeValue() {
        String input = "-456.78";
        BigDecimal expected = new BigDecimal("-456.78");
        BigDecimal result = NumberInput.parseBigDecimal(input);
        assertEquals(expected, result);
    }

    @Test
    public void testParseBigDecimal_ScientificNotation() {
        String input = "1.23E4";
        BigDecimal expected = new BigDecimal("1.23E4");
        BigDecimal result = NumberInput.parseBigDecimal(input);
        assertEquals(expected, result);
    }

    @Test
    public void testParseBigDecimal_Zero() {
        String input = "0";
        BigDecimal expected = BigDecimal.ZERO;
        BigDecimal result = NumberInput.parseBigDecimal(input);
        // Using compareTo for zero to handle scale differences if any, 
        // though new BigDecimal("0") matches BigDecimal.ZERO
        assertEquals(0, expected.compareTo(result));
    }

    @Test
    public void testParseBigDecimal_LeadingTrailingWhitespace() throws NumberFormatException {
        // Note: new BigDecimal(String) throws NumberFormatException if there are spaces.
        // This test ensures we know the behavior of the underlying constructor.
        try {
            NumberInput.parseBigDecimal(" 123 ");
        } catch (NumberFormatException e) {
            // Expected behavior for new BigDecimal(String)
        }
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidString() {
        String input = "abc";
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_EmptyString() {
        String input = "";
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NullPointerException.class)
    public void testParseBigDecimal_NullInput() {
        String input = null;
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_OnlyDecimalPoint() {
        String input = ".";
        NumberInput.parseBigDecimal(input);
    }

    @Test
    public void testParseBigDecimal_LargeValue() {
        String input = "123456789012345678901234567890";
        BigDecimal expected = new BigDecimal("123456789012345678901234567890");
        BigDecimal result = NumberInput.parseBigDecimal(input);
        assertEquals(expected, result);
    }
}
